#!/usr/bin/env python3
"""Apply the operator dashboard, OAuth, DSPy, and documentation cleanup."""

from __future__ import annotations

import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


def replace_once(path: str, old: str, new: str, label: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


def replace_between(path: str, start: str, end: str, replacement: str, label: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    start_index = text.find(start)
    if start_index < 0:
        raise RuntimeError(f"{label}: start marker not found")
    end_index = text.find(end, start_index)
    if end_index < 0:
        raise RuntimeError(f"{label}: end marker not found")
    target.write_text(
        text[:start_index] + replacement.rstrip() + "\n\n" + text[end_index:],
        encoding="utf-8",
    )


def remove(path: str) -> None:
    target = ROOT / path
    if target.is_dir():
        shutil.rmtree(target)
    elif target.exists():
        target.unlink()


write('src/cambium/observability.py', '"""Event-sourced operator view of a Cambium session.\n\nThe reducer consumes the durable supervisor event stream and derives a compact\nread model for terminal frontends.  It owns no runtime state and never reaches\ninto live workers: replaying the same ordered events produces the same agent\nand usage view.  Optional checkpoint inspection adds context-trunk byte counts;\nprovider-reported token counts remain the authority for exact prompt usage.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport math\nfrom collections import deque\nfrom collections.abc import Mapping, Sequence\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .summary_trunk import SUMMARY_ENTRY_OPEN\n\n_TERMINAL_STATES = frozenset({"succeeded", "failed", "cancelled", "exited"})\n_ACTIVE_STATES = frozenset({"starting", "active", "merging"})\n_STATE_PRIORITY = {\n    "queued": 0,\n    "starting": 1,\n    "active": 2,\n    "merging": 3,\n    "exited": 4,\n    "cancelled": 5,\n    "failed": 6,\n    "succeeded": 7,\n}\n_CONTEXT_EVENT_KINDS = frozenset(\n    {\n        "context_checkpoint",\n        "context_epoch_advanced",\n        "context_resume",\n        "context_fork",\n    }\n)\n\n\n@dataclass(frozen=True, slots=True)\nclass AgentSnapshot:\n    """One task/agent row in the operator read model."""\n\n    task_id: str\n    parent_task_id: str | None\n    role: str\n    state: str\n    generation: int\n    turn: int\n    epoch: int\n    provider: str | None\n    model: str | None\n    tool: str | None\n    calls: int\n    summary_calls: int\n    input_tokens: int\n    output_tokens: int\n    cached_tokens: int\n    total_tokens: int\n    output_tokens_per_s: float | None\n    estimated_cost_usd: float\n    last_seq: int\n    last_kind: str | None\n\n\n@dataclass(frozen=True, slots=True)\nclass ContextSnapshot:\n    """Latest known prompt/trunk shape for the selected root context."""\n\n    task_id: str | None\n    checkpoint_ref: str | None\n    epoch: int\n    exact_prompt_tokens: int | None\n    active_context_bytes: int\n    active_context_messages: int\n    stable_head_bytes: int\n    summary_trunk_bytes: int\n    summary_segments: int\n    raw_tail_bytes: int\n    estimated_trunk_tokens: int\n    estimated_raw_tail_tokens: int\n    approximate: bool\n\n\n@dataclass(frozen=True, slots=True)\nclass RecentEvent:\n    seq: int\n    kind: str\n    task_id: str | None\n    detail: str\n\n\n@dataclass(frozen=True, slots=True)\nclass SessionSnapshot:\n    """Immutable dashboard state derived from one ordered event prefix."""\n\n    session_status: str\n    agents: tuple[AgentSnapshot, ...]\n    active_agents: int\n    queued_agents: int\n    succeeded_agents: int\n    failed_agents: int\n    calls: int\n    summary_calls: int\n    input_tokens: int\n    output_tokens: int\n    cached_tokens: int\n    total_tokens: int\n    output_tokens_per_s: float\n    estimated_cost_usd: float\n    elapsed_s: float | None\n    context: ContextSnapshot\n    recent_events: tuple[RecentEvent, ...]\n    last_seq: int\n\n\n@dataclass(slots=True)\nclass _Agent:\n    task_id: str\n    parent_task_id: str | None = None\n    state: str = "queued"\n    generation: int = 0\n    turn: int = 0\n    epoch: int = 0\n    provider: str | None = None\n    model: str | None = None\n    tool: str | None = None\n    calls: int = 0\n    summary_calls: int = 0\n    input_tokens: int = 0\n    output_tokens: int = 0\n    cached_tokens: int = 0\n    total_tokens: int = 0\n    output_tokens_per_s: float | None = None\n    estimated_cost_usd: float = 0.0\n    last_seq: int = 0\n    last_kind: str | None = None\n    checkpoint_ref: str | None = None\n    exact_prompt_tokens: int | None = None\n    active_context_bytes: int = 0\n    active_context_messages: int = 0\n    summary_trunk_bytes: int = 0\n    summary_segments: int = 0\n    raw_tail_bytes: int = 0\n\n\ndef _payload(event: Mapping[str, Any]) -> Mapping[str, Any]:\n    value = event.get("payload")\n    return value if isinstance(value, Mapping) else {}\n\n\ndef _finite_non_negative(value: Any) -> float | None:\n    if isinstance(value, bool) or not isinstance(value, (int, float)):\n        return None\n    try:\n        number = float(value)\n    except (OverflowError, ValueError):\n        return None\n    if not math.isfinite(number) or number < 0:\n        return None\n    return number\n\n\ndef _count(value: Any) -> int:\n    number = _finite_non_negative(value)\n    return 0 if number is None else int(number)\n\n\ndef _usage_counts(payload: Mapping[str, Any]) -> tuple[int, int, int, int]:\n    usage = payload.get("usage")\n    if not isinstance(usage, Mapping):\n        return 0, 0, 0, 0\n\n    input_tokens = 0\n    for key in ("input_tokens", "prompt_tokens"):\n        if key in usage:\n            input_tokens = _count(usage.get(key))\n            break\n\n    output_tokens = 0\n    for key in ("output_tokens", "completion_tokens"):\n        if key in usage:\n            output_tokens = _count(usage.get(key))\n            break\n\n    cached_tokens = 0\n    for details_key in ("input_tokens_details", "prompt_tokens_details"):\n        details = usage.get(details_key)\n        if isinstance(details, Mapping) and "cached_tokens" in details:\n            cached_tokens = _count(details.get("cached_tokens"))\n            break\n    else:\n        for key in ("cache_read_input_tokens", "cached_tokens"):\n            if key in usage:\n                cached_tokens = _count(usage.get(key))\n                break\n\n    total_tokens = (\n        _count(usage.get("total_tokens"))\n        if "total_tokens" in usage\n        else input_tokens + output_tokens\n    )\n    return input_tokens, output_tokens, cached_tokens, total_tokens\n\n\ndef _event_seq(event: Mapping[str, Any], fallback: int) -> int:\n    value = event.get("seq")\n    return value if type(value) is int and value > 0 else fallback\n\n\ndef _event_time(event: Mapping[str, Any]) -> float | None:\n    value = event.get("monotonic_ms")\n    number = _finite_non_negative(value)\n    if number is not None:\n        return number / 1000.0\n    value = event.get("ts")\n    if isinstance(value, str):\n        try:\n            value = float(value)\n        except ValueError:\n            return None\n    return _finite_non_negative(value)\n\n\ndef _string(value: Any) -> str | None:\n    return value if isinstance(value, str) and value else None\n\n\ndef _event_detail(kind: str, payload: Mapping[str, Any]) -> str:\n    for key in (\n        "message",\n        "reason",\n        "failure_reason",\n        "status",\n        "tool",\n        "provider",\n        "model",\n        "assigned_provider",\n    ):\n        value = payload.get(key)\n        if isinstance(value, str) and value:\n            return value.replace("\\n", " ")[:160]\n    if kind == "usage_event":\n        _, output_tokens, _, total_tokens = _usage_counts(payload)\n        return f"tokens={total_tokens} out={output_tokens}"\n    return ""\n\n\ndef _set_state(agent: _Agent, state: str) -> None:\n    if agent.state in _TERMINAL_STATES and state not in _TERMINAL_STATES:\n        return\n    if state in _TERMINAL_STATES:\n        agent.state = state\n        return\n    if _STATE_PRIORITY.get(state, 0) >= _STATE_PRIORITY.get(agent.state, 0):\n        agent.state = state\n\n\ndef _message_bytes(messages: Sequence[Mapping[str, Any]]) -> int:\n    try:\n        return len(\n            json.dumps(\n                list(messages),\n                sort_keys=True,\n                separators=(",", ":"),\n                ensure_ascii=False,\n                allow_nan=False,\n            ).encode("utf-8")\n        )\n    except (TypeError, ValueError, UnicodeEncodeError):\n        return 0\n\n\ndef _checkpoint_path(session_dir: Path, checkpoint_ref: str) -> Path | None:\n    relative = Path(checkpoint_ref)\n    if relative.is_absolute() or ".." in relative.parts:\n        return None\n    roots = (\n        session_dir / ".cambium" / "checkpoints",\n        session_dir / ".cambium" / "context",\n        session_dir / ".cambium" / "epochs",\n        session_dir / ".cambium",\n        session_dir,\n    )\n    for root in roots:\n        candidate = root / relative\n        if candidate.is_file():\n            return candidate\n    state_root = session_dir / ".cambium"\n    if state_root.is_dir():\n        matches = tuple(state_root.rglob(relative.name))\n        for candidate in matches:\n            try:\n                candidate.relative_to(state_root)\n            except ValueError:\n                continue\n            if candidate.is_file():\n                return candidate\n    return None\n\n\ndef _read_checkpoint_context(\n    session_dir: Path | None,\n    checkpoint_ref: str | None,\n) -> tuple[int, int, int, int, int] | None:\n    """Return head, summary, segments, raw-tail, message-count byte metrics."""\n\n    if session_dir is None or checkpoint_ref is None:\n        return None\n    path = _checkpoint_path(session_dir, checkpoint_ref)\n    if path is None:\n        return None\n    try:\n        raw = path.read_bytes()\n        if len(raw) > 8 * 1024 * 1024:\n            return None\n        document = json.loads(raw)\n    except (OSError, UnicodeDecodeError, json.JSONDecodeError):\n        return None\n    if not isinstance(document, Mapping):\n        return None\n    provider_messages = document.get("provider_messages")\n    continuation = document.get("continuation_suffix")\n    if not isinstance(provider_messages, list) or not isinstance(continuation, list):\n        return None\n    messages = [item for item in provider_messages if isinstance(item, Mapping)]\n    suffix = [item for item in continuation if isinstance(item, Mapping)]\n    if len(messages) != len(provider_messages) or len(suffix) != len(continuation):\n        return None\n\n    stable_head = messages[:2]\n    summary_messages: list[Mapping[str, Any]] = []\n    index = 2\n    while index < len(messages):\n        content = messages[index].get("content")\n        if not isinstance(content, str) or not content.startswith(SUMMARY_ENTRY_OPEN):\n            break\n        summary_messages.append(messages[index])\n        index += 1\n    raw_tail = [*messages[index:], *suffix]\n    return (\n        _message_bytes(stable_head),\n        _message_bytes([*stable_head, *summary_messages]),\n        len(summary_messages),\n        _message_bytes(raw_tail),\n        len(messages) + len(suffix),\n    )\n\n\nclass ObservabilityState:\n    """Incremental fold of durable events into an operator read model."""\n\n    def __init__(self, *, recent_limit: int = 12) -> None:\n        self._agents: dict[str, _Agent] = {}\n        self._order: list[str] = []\n        self._recent: deque[RecentEvent] = deque(maxlen=max(1, recent_limit))\n        self._last_seq = 0\n        self._synthetic_seq = 0\n        self._first_time: float | None = None\n        self._last_time: float | None = None\n        self._session_status = "idle"\n\n    @property\n    def last_seq(self) -> int:\n        return self._last_seq\n\n    def _ensure_agent(self, task_id: str) -> _Agent:\n        agent = self._agents.get(task_id)\n        if agent is None:\n            agent = _Agent(task_id=task_id)\n            self._agents[task_id] = agent\n            self._order.append(task_id)\n        return agent\n\n    def apply(self, event: Mapping[str, Any]) -> None:\n        if not isinstance(event, Mapping):\n            return\n        self._synthetic_seq += 1\n        seq = _event_seq(event, self._synthetic_seq)\n        if type(event.get("seq")) is int and seq <= self._last_seq:\n            return\n        self._last_seq = max(self._last_seq, seq)\n        kind = _string(event.get("kind")) or "event"\n        payload = _payload(event)\n        task_id = _string(event.get("task_id"))\n        generation = event.get("generation")\n        timestamp = _event_time(event)\n        if timestamp is not None:\n            self._first_time = timestamp if self._first_time is None else self._first_time\n            self._last_time = timestamp\n\n        parent_id = _string(payload.get("parent_task_id"))\n        child_id = _string(payload.get("child_task_id"))\n        if child_id is not None:\n            child = self._ensure_agent(child_id)\n            if parent_id is not None:\n                child.parent_task_id = parent_id\n        if task_id is not None:\n            agent = self._ensure_agent(task_id)\n            if parent_id is not None and task_id != parent_id:\n                agent.parent_task_id = parent_id\n            if type(generation) is int and generation >= 0:\n                agent.generation = max(agent.generation, generation)\n            agent.last_seq = seq\n            agent.last_kind = kind\n\n            if kind in {"task_assigned", "child_admitted"}:\n                _set_state(agent, "queued")\n            elif kind == "spawned":\n                _set_state(agent, "starting")\n            elif kind in {\n                "ready",\n                "run_task",\n                "heartbeat",\n                "tool_event",\n                "checkpoint",\n                "usage_event",\n                "context_checkpoint",\n                "context_epoch_advanced",\n                "context_resume",\n                "context_fork",\n            }:\n                _set_state(agent, "active")\n            elif kind in {"merge_progress", "merge_started"}:\n                _set_state(agent, "merging")\n            elif kind in {"worker_failed", "task_failed", "context_resume_failed"}:\n                _set_state(agent, "failed")\n            elif kind == "result":\n                status = _string(payload.get("status"))\n                if status in {"succeeded", "failed", "cancelled"}:\n                    _set_state(agent, status)\n            elif kind == "exit":\n                _set_state(agent, "exited")\n            elif kind == "reuse_ready" and agent.state not in _TERMINAL_STATES:\n                _set_state(agent, "succeeded")\n            elif kind in {"cancelled", "task_cancelled"}:\n                _set_state(agent, "cancelled")\n\n            turn = payload.get("turn")\n            if type(turn) is int and turn >= 0:\n                agent.turn = max(agent.turn, turn)\n            epoch = payload.get("epoch")\n            if type(epoch) is int and epoch >= 0:\n                agent.epoch = max(agent.epoch, epoch)\n\n            provider = _string(payload.get("provider")) or _string(\n                payload.get("assigned_provider")\n            )\n            model = _string(payload.get("model"))\n            if provider is not None:\n                agent.provider = provider\n            if model is not None:\n                agent.model = model\n            tool = _string(payload.get("tool"))\n            if tool is not None:\n                agent.tool = tool\n\n            if kind == "usage_event":\n                (\n                    input_tokens,\n                    output_tokens,\n                    cached_tokens,\n                    total_tokens,\n                ) = _usage_counts(payload)\n                agent.calls += 1\n                if payload.get("call_kind") == "summary":\n                    agent.summary_calls += 1\n                agent.input_tokens += input_tokens\n                agent.output_tokens += output_tokens\n                agent.cached_tokens += cached_tokens\n                agent.total_tokens += total_tokens\n                latency = _finite_non_negative(payload.get("latency_s"))\n                if latency is not None and latency > 0:\n                    agent.output_tokens_per_s = output_tokens / latency\n                cost = _finite_non_negative(payload.get("estimated_cost_usd"))\n                if cost is not None:\n                    agent.estimated_cost_usd += cost\n                if input_tokens > 0:\n                    agent.exact_prompt_tokens = input_tokens\n                for field in (\n                    "active_context_bytes",\n                    "active_context_messages",\n                    "summary_trunk_bytes",\n                    "summary_segments",\n                    "raw_tail_bytes",\n                ):\n                    value = payload.get(field)\n                    if type(value) is int and value >= 0:\n                        setattr(agent, field, value)\n\n            if kind in _CONTEXT_EVENT_KINDS:\n                checkpoint_ref = _string(payload.get("checkpoint_ref"))\n                if checkpoint_ref is not None:\n                    agent.checkpoint_ref = checkpoint_ref\n                cache_key = payload.get("cache_key")\n                if isinstance(cache_key, Mapping):\n                    prefix_bytes = cache_key.get("prefix_bytes")\n                    if type(prefix_bytes) is int and prefix_bytes >= 0:\n                        agent.active_context_bytes = max(\n                            agent.active_context_bytes, prefix_bytes\n                        )\n                    message_count = cache_key.get("message_count")\n                    if type(message_count) is int and message_count >= 0:\n                        agent.active_context_messages = max(\n                            agent.active_context_messages, message_count\n                        )\n\n        if kind in {"session_started", "session_resumed"}:\n            self._session_status = "running"\n        elif kind == "session_ended":\n            self._session_status = _string(payload.get("session_status")) or "ended"\n        elif kind in {"session_cancelled", "shutdown"}:\n            self._session_status = "cancelled"\n        elif self._session_status == "idle" and task_id is not None:\n            self._session_status = "running"\n\n        self._recent.append(\n            RecentEvent(\n                seq=seq,\n                kind=kind,\n                task_id=task_id,\n                detail=_event_detail(kind, payload),\n            )\n        )\n\n    def extend(self, events: Sequence[Mapping[str, Any]]) -> None:\n        for event in events:\n            self.apply(event)\n\n    def _root_task_id(self) -> str | None:\n        for task_id in self._order:\n            if self._agents[task_id].parent_task_id is None:\n                return task_id\n        return self._order[0] if self._order else None\n\n    def snapshot(self, *, session_dir: str | Path | None = None) -> SessionSnapshot:\n        root_task_id = self._root_task_id()\n        snapshots: list[AgentSnapshot] = []\n        for task_id in self._order:\n            agent = self._agents[task_id]\n            role = "main" if task_id == root_task_id else "sub"\n            snapshots.append(\n                AgentSnapshot(\n                    task_id=agent.task_id,\n                    parent_task_id=agent.parent_task_id,\n                    role=role,\n                    state=agent.state,\n                    generation=agent.generation,\n                    turn=agent.turn,\n                    epoch=agent.epoch,\n                    provider=agent.provider,\n                    model=agent.model,\n                    tool=agent.tool,\n                    calls=agent.calls,\n                    summary_calls=agent.summary_calls,\n                    input_tokens=agent.input_tokens,\n                    output_tokens=agent.output_tokens,\n                    cached_tokens=agent.cached_tokens,\n                    total_tokens=agent.total_tokens,\n                    output_tokens_per_s=agent.output_tokens_per_s,\n                    estimated_cost_usd=round(agent.estimated_cost_usd, 6),\n                    last_seq=agent.last_seq,\n                    last_kind=agent.last_kind,\n                )\n            )\n\n        root = self._agents.get(root_task_id) if root_task_id is not None else None\n        context_agent = root\n        if context_agent is None or context_agent.checkpoint_ref is None:\n            context_agent = next(\n                (\n                    self._agents[task_id]\n                    for task_id in reversed(self._order)\n                    if self._agents[task_id].checkpoint_ref is not None\n                ),\n                context_agent,\n            )\n\n        checkpoint_metrics = _read_checkpoint_context(\n            Path(session_dir).expanduser().resolve()\n            if session_dir is not None\n            else None,\n            context_agent.checkpoint_ref if context_agent is not None else None,\n        )\n        stable_head_bytes = 0\n        summary_trunk_bytes = (\n            context_agent.summary_trunk_bytes if context_agent is not None else 0\n        )\n        summary_segments = (\n            context_agent.summary_segments if context_agent is not None else 0\n        )\n        raw_tail_bytes = context_agent.raw_tail_bytes if context_agent is not None else 0\n        active_context_messages = (\n            context_agent.active_context_messages if context_agent is not None else 0\n        )\n        approximate = True\n        if checkpoint_metrics is not None:\n            (\n                stable_head_bytes,\n                checkpoint_trunk_bytes,\n                checkpoint_segments,\n                checkpoint_raw_bytes,\n                checkpoint_messages,\n            ) = checkpoint_metrics\n            summary_trunk_bytes = max(summary_trunk_bytes, checkpoint_trunk_bytes)\n            summary_segments = max(summary_segments, checkpoint_segments)\n            raw_tail_bytes = max(raw_tail_bytes, checkpoint_raw_bytes)\n            active_context_messages = max(active_context_messages, checkpoint_messages)\n        active_context_bytes = (\n            context_agent.active_context_bytes if context_agent is not None else 0\n        )\n        active_context_bytes = max(\n            active_context_bytes, summary_trunk_bytes + raw_tail_bytes\n        )\n        context = ContextSnapshot(\n            task_id=context_agent.task_id if context_agent is not None else None,\n            checkpoint_ref=(\n                context_agent.checkpoint_ref if context_agent is not None else None\n            ),\n            epoch=context_agent.epoch if context_agent is not None else 0,\n            exact_prompt_tokens=(\n                context_agent.exact_prompt_tokens if context_agent is not None else None\n            ),\n            active_context_bytes=active_context_bytes,\n            active_context_messages=active_context_messages,\n            stable_head_bytes=stable_head_bytes,\n            summary_trunk_bytes=summary_trunk_bytes,\n            summary_segments=summary_segments,\n            raw_tail_bytes=raw_tail_bytes,\n            estimated_trunk_tokens=round(summary_trunk_bytes / 4),\n            estimated_raw_tail_tokens=round(raw_tail_bytes / 4),\n            approximate=approximate,\n        )\n\n        calls = sum(agent.calls for agent in self._agents.values())\n        summary_calls = sum(agent.summary_calls for agent in self._agents.values())\n        input_tokens = sum(agent.input_tokens for agent in self._agents.values())\n        output_tokens = sum(agent.output_tokens for agent in self._agents.values())\n        cached_tokens = sum(agent.cached_tokens for agent in self._agents.values())\n        total_tokens = sum(agent.total_tokens for agent in self._agents.values())\n        cost = sum(agent.estimated_cost_usd for agent in self._agents.values())\n        rates = [\n            agent.output_tokens_per_s\n            for agent in self._agents.values()\n            if agent.output_tokens_per_s is not None and agent.state in _ACTIVE_STATES\n        ]\n        elapsed_s = (\n            max(0.0, self._last_time - self._first_time)\n            if self._first_time is not None and self._last_time is not None\n            else None\n        )\n        return SessionSnapshot(\n            session_status=self._session_status,\n            agents=tuple(snapshots),\n            active_agents=sum(\n                snapshot.state in _ACTIVE_STATES for snapshot in snapshots\n            ),\n            queued_agents=sum(snapshot.state == "queued" for snapshot in snapshots),\n            succeeded_agents=sum(\n                snapshot.state == "succeeded" for snapshot in snapshots\n            ),\n            failed_agents=sum(\n                snapshot.state in {"failed", "cancelled"} for snapshot in snapshots\n            ),\n            calls=calls,\n            summary_calls=summary_calls,\n            input_tokens=input_tokens,\n            output_tokens=output_tokens,\n            cached_tokens=cached_tokens,\n            total_tokens=total_tokens,\n            output_tokens_per_s=sum(rates),\n            estimated_cost_usd=round(cost, 6),\n            elapsed_s=elapsed_s,\n            context=context,\n            recent_events=tuple(self._recent),\n            last_seq=self._last_seq,\n        )\n\n\ndef snapshot_from_events(\n    events: Sequence[Mapping[str, Any]],\n    *,\n    session_dir: str | Path | None = None,\n    recent_limit: int = 12,\n) -> SessionSnapshot:\n    state = ObservabilityState(recent_limit=recent_limit)\n    state.extend(events)\n    return state.snapshot(session_dir=session_dir)\n\n\n__all__ = [\n    "AgentSnapshot",\n    "ContextSnapshot",\n    "ObservabilityState",\n    "RecentEvent",\n    "SessionSnapshot",\n    "snapshot_from_events",\n]\n')
write('src/cambium/monitor.py', '"""OpenCode-style terminal dashboard for live Cambium sessions.\n\nThe monitor is a projection over durable events and immutable checkpoints.  It\ncan attach to an existing session, or it can be embedded by ``cambium tui``\nwhile a one-shot run is active.  The renderer never mutates supervisor state.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport shutil\nimport sys\nimport time\nfrom dataclasses import asdict\nfrom pathlib import Path\nfrom typing import Any, TextIO\n\nfrom .observability import (\n    AgentSnapshot,\n    ObservabilityState,\n    SessionSnapshot,\n)\nfrom .store import StoreError, read_events_file\n\n_ALT_ENTER = "\\x1b[?1049h\\x1b[?25l"\n_ALT_EXIT = "\\x1b[?25h\\x1b[?1049l"\n_HOME_CLEAR = "\\x1b[H\\x1b[2J"\n\n\ndef _is_tty(stream: Any) -> bool:\n    try:\n        return bool(getattr(stream, "isatty", lambda: False)())\n    except (AttributeError, OSError):\n        return False\n\n\ndef _clip(value: str, width: int) -> str:\n    if width <= 0:\n        return ""\n    if len(value) <= width:\n        return value\n    if width == 1:\n        return "…"\n    return value[: width - 1] + "…"\n\n\ndef _human_count(value: int) -> str:\n    if value < 1_000:\n        return str(value)\n    if value < 1_000_000:\n        rendered = f"{value / 1_000:.1f}".rstrip("0").rstrip(".")\n        return f"{rendered}k"\n    rendered = f"{value / 1_000_000:.1f}".rstrip("0").rstrip(".")\n    return f"{rendered}m"\n\n\ndef _human_bytes(value: int) -> str:\n    if value < 1_024:\n        return f"{value}B"\n    if value < 1_024 * 1_024:\n        rendered = f"{value / 1_024:.1f}".rstrip("0").rstrip(".")\n        return f"{rendered}KiB"\n    rendered = f"{value / (1_024 * 1_024):.1f}".rstrip("0").rstrip(".")\n    return f"{rendered}MiB"\n\n\ndef _duration(value: float | None) -> str:\n    if value is None:\n        return "?"\n    seconds = max(0, int(value))\n    hours, remainder = divmod(seconds, 3600)\n    minutes, seconds = divmod(remainder, 60)\n    if hours:\n        return f"{hours}h{minutes:02d}m"\n    if minutes:\n        return f"{minutes}m{seconds:02d}s"\n    return f"{seconds}s"\n\n\ndef _model(agent: AgentSnapshot) -> str:\n    if agent.provider and agent.model:\n        return f"{agent.provider}/{agent.model}"\n    return agent.model or agent.provider or "?"\n\n\ndef _rate(agent: AgentSnapshot) -> str:\n    value = agent.output_tokens_per_s\n    return "?" if value is None else f"{value:.1f}"\n\n\ndef _border(title: str, width: int) -> str:\n    inner = max(0, width - 2)\n    label = f" {title} "\n    if len(label) > inner:\n        label = _clip(label, inner)\n    return "┌" + label + "─" * max(0, inner - len(label)) + "┐"\n\n\ndef _rule(title: str, width: int) -> str:\n    inner = max(0, width - 2)\n    label = f" {title} "\n    if len(label) > inner:\n        label = _clip(label, inner)\n    return "├" + label + "─" * max(0, inner - len(label)) + "┤"\n\n\ndef _inside(content: str, width: int) -> str:\n    inner = max(0, width - 2)\n    return "│" + _clip(content, inner).ljust(inner) + "│"\n\n\ndef _bottom(width: int) -> str:\n    return "└" + "─" * max(0, width - 2) + "┘"\n\n\ndef render_agent_lines(snapshot: SessionSnapshot) -> list[str]:\n    """Stable non-boxed agent report used by CLI status and tests."""\n\n    lines: list[str] = []\n    for agent in snapshot.agents:\n        parent = agent.parent_task_id or "-"\n        lines.append(\n            f"{agent.task_id:<24} {agent.state:<9} role={agent.role} "\n            f"parent={parent} gen={agent.generation} turn={agent.turn} "\n            f"epoch={agent.epoch} model={_model(agent)} calls={agent.calls} "\n            f"tokens={agent.total_tokens} in={agent.input_tokens} "\n            f"out={agent.output_tokens} cached={agent.cached_tokens} "\n            f"out/s={_rate(agent)} cost=${agent.estimated_cost_usd:.6f}"\n        )\n    lines.append(\n        f"totals: tokens={snapshot.total_tokens} in={snapshot.input_tokens} "\n        f"out={snapshot.output_tokens} cached={snapshot.cached_tokens} "\n        f"calls={snapshot.calls} summaries={snapshot.summary_calls} "\n        f"out/s={snapshot.output_tokens_per_s:.1f} "\n        f"cost=${snapshot.estimated_cost_usd:.6f}"\n    )\n    return lines\n\n\ndef render_dashboard(\n    snapshot: SessionSnapshot,\n    *,\n    session_dir: str | Path,\n    width: int = 120,\n    height: int = 40,\n) -> list[str]:\n    """Render one full dashboard frame without terminal control sequences."""\n\n    width = max(60, width)\n    height = max(18, height)\n    session = str(Path(session_dir).expanduser())\n    lines = [_border("Cambium", width)]\n    lines.append(\n        _inside(\n            f"session {_clip(session, max(10, width - 45))}  "\n            f"status={snapshot.session_status}  elapsed={_duration(snapshot.elapsed_s)}  "\n            f"seq={snapshot.last_seq}",\n            width,\n        )\n    )\n    lines.append(\n        _inside(\n            "agents "\n            f"active={snapshot.active_agents} queued={snapshot.queued_agents} "\n            f"ok={snapshot.succeeded_agents} failed={snapshot.failed_agents}  "\n            "usage "\n            f"in={_human_count(snapshot.input_tokens)} "\n            f"out={_human_count(snapshot.output_tokens)} "\n            f"cache={_human_count(snapshot.cached_tokens)} "\n            f"total={_human_count(snapshot.total_tokens)} "\n            f"calls={snapshot.calls} summaries={snapshot.summary_calls} "\n            f"out/s={snapshot.output_tokens_per_s:.1f} "\n            f"cost=${snapshot.estimated_cost_usd:.4f}",\n            width,\n        )\n    )\n    context = snapshot.context\n    prompt_tokens = (\n        "?" if context.exact_prompt_tokens is None else _human_count(context.exact_prompt_tokens)\n    )\n    lines.append(\n        _inside(\n            "context "\n            f"task={context.task_id or \'?\'} epoch={context.epoch} "\n            f"prompt={prompt_tokens}tok "\n            f"trunk≈{_human_count(context.estimated_trunk_tokens)}tok/"\n            f"{_human_bytes(context.summary_trunk_bytes)} "\n            f"segments={context.summary_segments} "\n            f"raw≈{_human_count(context.estimated_raw_tail_tokens)}tok/"\n            f"{_human_bytes(context.raw_tail_bytes)} "\n            f"messages={context.active_context_messages}",\n            width,\n        )\n    )\n\n    lines.append(_rule("agents", width))\n    compact = width < 105\n    if compact:\n        header = (\n            " R  TASK                 STATE      MODEL                    "\n            "TURN  TOKENS   OUT/S TOOL"\n        )\n    else:\n        header = (\n            " R  TASK                     STATE      MODEL                              "\n            "GEN TURN EP   IN      OUT     CACHE   TOTAL   OUT/S TOOL"\n        )\n    lines.append(_inside(header, width))\n\n    reserved = 6  # top/bottom/rules\n    event_rows = min(8, max(3, height // 4))\n    agent_capacity = max(3, height - reserved - event_rows - 3)\n    agents = snapshot.agents[-agent_capacity:]\n    for agent in agents:\n        role = "M" if agent.role == "main" else "S"\n        tool = agent.tool or "-"\n        if compact:\n            row = (\n                f" {role}  {_clip(agent.task_id, 20):<20} "\n                f"{agent.state:<10} {_clip(_model(agent), 24):<24} "\n                f"{agent.turn:>4} {_human_count(agent.total_tokens):>7} "\n                f"{_rate(agent):>7} {_clip(tool, 14)}"\n            )\n        else:\n            row = (\n                f" {role}  {_clip(agent.task_id, 24):<24} "\n                f"{agent.state:<10} {_clip(_model(agent), 34):<34} "\n                f"{agent.generation:>3} {agent.turn:>4} {agent.epoch:>2} "\n                f"{_human_count(agent.input_tokens):>7} "\n                f"{_human_count(agent.output_tokens):>7} "\n                f"{_human_count(agent.cached_tokens):>7} "\n                f"{_human_count(agent.total_tokens):>7} "\n                f"{_rate(agent):>6} {_clip(tool, 16)}"\n            )\n        lines.append(_inside(row, width))\n    if not agents:\n        lines.append(_inside(" no agents observed yet", width))\n\n    lines.append(_rule("recent durable events", width))\n    recent = snapshot.recent_events[-event_rows:]\n    for event in recent:\n        task = event.task_id or "-"\n        detail = f"  {event.detail}" if event.detail else ""\n        lines.append(\n            _inside(\n                f" #{event.seq:<6} {_clip(event.kind, 24):<24} "\n                f"{_clip(task, 24):<24}{detail}",\n                width,\n            )\n        )\n    if not recent:\n        lines.append(_inside(" waiting for events", width))\n    while len(lines) < height - 2:\n        lines.append(_inside("", width))\n    lines.append(_inside("Ctrl-C/q: close monitor  •  runtime continues unless its owner cancels it", width))\n    lines.append(_bottom(width))\n    return lines[:height]\n\n\ndef snapshot_json(snapshot: SessionSnapshot) -> str:\n    return json.dumps(asdict(snapshot), sort_keys=True, separators=(",", ":"))\n\n\nclass AnsiDashboard:\n    """Small alternate-screen renderer for an already-owned event stream."""\n\n    def __init__(\n        self,\n        session_dir: str | Path,\n        *,\n        stream: TextIO | None = None,\n        enabled: bool = True,\n    ) -> None:\n        self.session_dir = Path(session_dir)\n        self.stream = sys.stdout if stream is None else stream\n        self.enabled = enabled and _is_tty(self.stream)\n        self._entered = False\n\n    def __enter__(self) -> AnsiDashboard:\n        if self.enabled:\n            self.stream.write(_ALT_ENTER)\n            self.stream.flush()\n            self._entered = True\n        return self\n\n    def draw(self, snapshot: SessionSnapshot) -> None:\n        if not self.enabled:\n            return\n        size = shutil.get_terminal_size((120, 40))\n        lines = render_dashboard(\n            snapshot,\n            session_dir=self.session_dir,\n            width=size.columns,\n            height=size.lines,\n        )\n        self.stream.write(_HOME_CLEAR)\n        self.stream.write("\\n".join(lines))\n        self.stream.flush()\n\n    def __exit__(self, exc_type, exc, tb) -> None:\n        del exc_type, exc, tb\n        if self._entered:\n            self.stream.write(_ALT_EXIT)\n            self.stream.flush()\n            self._entered = False\n\n\ndef _latest_session(repo: Path) -> Path | None:\n    candidates: list[Path] = []\n    direct = repo / ".cambium" / "events.db"\n    if direct.is_file():\n        candidates.append(repo)\n    roots = (\n        repo / ".cambium" / "sessions",\n        Path.cwd() / ".cambium" / "sessions",\n    )\n    for root in roots:\n        if not root.is_dir():\n            continue\n        candidates.extend(\n            path\n            for path in root.iterdir()\n            if path.is_dir() and (path / ".cambium" / "events.db").is_file()\n        )\n    if not candidates:\n        return None\n    return max(\n        candidates,\n        key=lambda path: (path / ".cambium" / "events.db").stat().st_mtime_ns,\n    )\n\n\ndef resolve_session(value: str | Path | None, *, repo: str | Path = ".") -> Path:\n    if value is not None:\n        session = Path(value).expanduser().resolve()\n    else:\n        env_value = os.environ.get("CAMBIUM_SESSION_ID")\n        if env_value:\n            session = Path(env_value).expanduser().resolve()\n        else:\n            latest = _latest_session(Path(repo).expanduser().resolve())\n            if latest is None:\n                raise ValueError("no Cambium session with an event log was found")\n            session = latest.resolve()\n    event_db = session / ".cambium" / "events.db"\n    if not event_db.is_file():\n        raise ValueError(f"session event log is missing: {event_db}")\n    return session\n\n\ndef monitor_session(\n    session_dir: str | Path,\n    *,\n    interval_s: float = 0.25,\n    once: bool = False,\n    json_output: bool = False,\n    output_stream: TextIO | None = None,\n) -> int:\n    session = resolve_session(session_dir)\n    out = sys.stdout if output_stream is None else output_stream\n    state = ObservabilityState()\n    dashboard = AnsiDashboard(session, stream=out, enabled=not once and not json_output)\n    try:\n        with dashboard:\n            while True:\n                events = read_events_file(\n                    session / ".cambium" / "events.db",\n                    after_seq=state.last_seq,\n                )\n                state.extend(events)\n                snapshot = state.snapshot(session_dir=session)\n                if json_output:\n                    out.write(snapshot_json(snapshot) + "\\n")\n                    out.flush()\n                    return 0\n                if once or not dashboard.enabled:\n                    out.write("\\n".join(render_dashboard(snapshot, session_dir=session)) + "\\n")\n                    out.flush()\n                    return 0\n                dashboard.draw(snapshot)\n                if (\n                    snapshot.session_status in {"ended", "cancelled", "failed"}\n                    and snapshot.active_agents == 0\n                    and snapshot.queued_agents == 0\n                ):\n                    time.sleep(min(interval_s, 0.25))\n                    return 0\n                time.sleep(interval_s)\n    except KeyboardInterrupt:\n        return 130\n    except (OSError, StoreError, ValueError) as exc:\n        print(f"cambium monitor: {exc}", file=sys.stderr)\n        return 1\n\n\ndef _parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(\n        prog="cambium monitor",\n        description="Attach an OpenCode-style dashboard to a durable Cambium session.",\n    )\n    parser.add_argument("session", nargs="?", help="session directory; defaults to the newest")\n    parser.add_argument("--repo", default=".", help="repository used for session discovery")\n    parser.add_argument("--interval", type=float, default=0.25, metavar="SECONDS")\n    parser.add_argument("--once", action="store_true", help="render one frame and exit")\n    parser.add_argument("--json", action="store_true", help="emit one JSON snapshot and exit")\n    return parser\n\n\ndef main(argv: list[str] | None = None) -> int:\n    args = _parser().parse_args(argv)\n    if not math_is_positive(args.interval):\n        print("cambium monitor: --interval must be a positive finite number", file=sys.stderr)\n        return 2\n    try:\n        session = resolve_session(args.session, repo=args.repo)\n    except ValueError as exc:\n        print(f"cambium monitor: {exc}", file=sys.stderr)\n        return 1\n    return monitor_session(\n        session,\n        interval_s=args.interval,\n        once=args.once,\n        json_output=args.json,\n    )\n\n\ndef math_is_positive(value: Any) -> bool:\n    try:\n        number = float(value)\n    except (TypeError, ValueError, OverflowError):\n        return False\n    return number > 0 and number < float("inf")\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n\n\n__all__ = [\n    "AnsiDashboard",\n    "main",\n    "monitor_session",\n    "render_agent_lines",\n    "render_dashboard",\n    "resolve_session",\n    "snapshot_json",\n]\n')
write('src/cambium/tui.py', '"""Interactive terminal frontend with an event-sourced live dashboard."""\n\nfrom __future__ import annotations\n\nimport sqlite3\nimport sys\nfrom dataclasses import replace\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .monitor import AnsiDashboard\nfrom .observability import ObservabilityState\n\n_PROMPT = "cambium> "\n\n\ndef _is_tty(stream: Any) -> bool:\n    try:\n        return bool(getattr(stream, "isatty", lambda: False)())\n    except (AttributeError, OSError):\n        return False\n\n\ndef _write_line(out: Any, line: str) -> None:\n    if line:\n        out.write(line)\n        if not line.endswith("\\n"):\n            out.write("\\n")\n\n\nasync def run_tui(\n    config, *, input_stream=None, output_stream=None, error_stream=None, quiet=False\n) -> int:\n    """Run prompts and show one OpenCode-style dashboard while each run is active."""\n\n    source = sys.stdin if input_stream is None else input_stream\n    out = sys.stdout if output_stream is None else output_stream\n    err = sys.stderr if error_stream is None else error_stream\n    dashboard_enabled = _is_tty(out) and not quiet\n\n    try:\n        from cambium import oneshot, render, stats\n    except ImportError as exc:\n        err.write(f"cambium tui: {exc}\\n")\n        err.flush()\n        from cambium.cli import ExitCode\n\n        return ExitCode.FAILURE\n\n    from cambium.auth import AuthError\n    from cambium.cli import ExitCode\n    from cambium.supervisor import SessionAlreadyRunningError\n\n    failed = False\n    try:\n        while True:\n            out.write(_PROMPT)\n            out.flush()\n            line = source.readline()\n            if line == "":\n                out.write("\\n")\n                out.flush()\n                return ExitCode.FAILURE if failed else ExitCode.SUCCESS\n            prompt = line.rstrip("\\r\\n")\n            if not prompt.strip():\n                continue\n            try:\n                session_dir = (\n                    Path(config.session_root).expanduser().resolve()\n                    if config.session_root is not None\n                    else oneshot.allocate_session_dir(oneshot.resolve_repo(config.repo))\n                )\n                prompt_config = replace(config, prompt=prompt, session_root=session_dir)\n                state = ObservabilityState()\n                dashboard = AnsiDashboard(\n                    session_dir,\n                    stream=out,\n                    enabled=dashboard_enabled,\n                )\n\n                def _live_sink(\n                    record: dict[str, Any],\n                    _state: ObservabilityState = state,\n                    _dashboard: AnsiDashboard = dashboard,\n                    _session_dir: Path = session_dir,\n                ) -> None:\n                    _state.apply(record)\n                    if _dashboard.enabled:\n                        _dashboard.draw(_state.snapshot(session_dir=_session_dir))\n                    elif not quiet:\n                        _write_line(out, render.render_event_line(record))\n                        snapshot = _state.snapshot()\n                        _write_line(\n                            out,\n                            "live: "\n                            f"out/s={snapshot.output_tokens_per_s:.1f} · "\n                            f"active={snapshot.active_agents} · "\n                            f"tokens={snapshot.total_tokens}",\n                        )\n                    out.flush()\n\n                with dashboard:\n                    response = await oneshot.run_oneshot(\n                        prompt_config,\n                        on_event=_live_sink,\n                    )\n                    if dashboard.enabled:\n                        dashboard.draw(state.snapshot(session_dir=session_dir))\n                text = render.render_text_result(response)\n                if response.exit_code != 0:\n                    failed = True\n            except BrokenPipeError:\n                return ExitCode.SUCCESS\n            except (AuthError, OSError, SessionAlreadyRunningError, ValueError) as exc:\n                failed = True\n                err.write(f"cambium tui: {exc}\\n")\n                err.flush()\n                continue\n            out.write(text)\n            if not text.endswith("\\n"):\n                out.write("\\n")\n            try:\n                worktree = (\n                    str(prompt_config.worktree_path)\n                    if prompt_config.worktree_path is not None\n                    else str(session_dir / "wt")\n                )\n                stats_line = render.render_usage_stats_line(\n                    stats.session_usage_stats(session_dir), worktree=worktree\n                )\n            except (OSError, ValueError, sqlite3.Error) as exc:\n                err.write(f"cambium tui: usage stats unavailable: {exc}\\n")\n                err.flush()\n                stats_line = ""\n            if stats_line:\n                out.write(stats_line)\n                if not stats_line.endswith("\\n"):\n                    out.write("\\n")\n            out.flush()\n    except KeyboardInterrupt:\n        out.write("\\n")\n        out.flush()\n        return ExitCode.INTERRUPTED\n    except BrokenPipeError:\n        return ExitCode.SUCCESS\n\n\n__all__ = ["run_tui"]\n')
write('tests/scenarios/test_observability.py', '"""Event-sourced operator dashboard regressions."""\n\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nfrom cambium.monitor import render_agent_lines, render_dashboard\nfrom cambium.observability import ObservabilityState, snapshot_from_events\nfrom cambium.summary_trunk import SUMMARY_ENTRY_CLOSE, SUMMARY_ENTRY_OPEN\n\n\ndef _event(\n    seq: int,\n    kind: str,\n    *,\n    task_id: str | None = None,\n    generation: int = 1,\n    **payload,\n) -> dict:\n    record = {\n        "seq": seq,\n        "kind": kind,\n        "payload": payload,\n        "generation": generation,\n        "monotonic_ms": seq * 100,\n    }\n    if task_id is not None:\n        record["task_id"] = task_id\n    return record\n\n\ndef test_reducer_exposes_main_and_subagent_usage_and_models() -> None:\n    events = [\n        _event(1, "session_started"),\n        _event(2, "task_assigned", task_id="root", assigned_provider="codex", model="gpt"),\n        _event(3, "spawned", task_id="root"),\n        _event(\n            4,\n            "usage_event",\n            task_id="root",\n            provider="codex",\n            model="gpt",\n            turn=1,\n            latency_s=2.0,\n            call_kind="agent",\n            active_context_bytes=4_000,\n            active_context_messages=8,\n            summary_trunk_bytes=3_000,\n            summary_segments=2,\n            raw_tail_bytes=1_000,\n            usage={\n                "input_tokens": 1_000,\n                "output_tokens": 100,\n                "cached_tokens": 600,\n                "total_tokens": 1_100,\n            },\n            estimated_cost_usd=0.01,\n        ),\n        _event(\n            5,\n            "child_admitted",\n            task_id="root",\n            parent_task_id="root",\n            child_task_id="child",\n        ),\n        _event(6, "spawned", task_id="child"),\n        _event(\n            7,\n            "usage_event",\n            task_id="child",\n            provider="zai",\n            model="glm",\n            turn=1,\n            latency_s=1.0,\n            call_kind="summary",\n            usage={\n                "prompt_tokens": 200,\n                "completion_tokens": 50,\n                "total_tokens": 250,\n            },\n            estimated_cost_usd=0.002,\n        ),\n        _event(8, "result", task_id="child", status="succeeded"),\n    ]\n\n    snapshot = snapshot_from_events(events)\n    assert [agent.role for agent in snapshot.agents] == ["main", "sub"]\n    root, child = snapshot.agents\n    assert root.state == "active"\n    assert root.provider == "codex"\n    assert root.model == "gpt"\n    assert root.input_tokens == 1_000\n    assert root.output_tokens_per_s == 50.0\n    assert child.parent_task_id == "root"\n    assert child.state == "succeeded"\n    assert child.summary_calls == 1\n    assert child.output_tokens_per_s == 50.0\n    assert snapshot.total_tokens == 1_350\n    assert snapshot.cached_tokens == 600\n    assert snapshot.output_tokens_per_s == 50.0\n    assert snapshot.context.summary_segments == 2\n    assert snapshot.context.exact_prompt_tokens == 1_000\n\n\ndef test_terminal_state_is_not_overwritten_by_late_heartbeat() -> None:\n    state = ObservabilityState()\n    state.extend(\n        [\n            _event(1, "spawned", task_id="root"),\n            _event(2, "result", task_id="root", status="failed"),\n            _event(3, "heartbeat", task_id="root", turn=9),\n        ]\n    )\n    snapshot = state.snapshot()\n    assert snapshot.agents[0].state == "failed"\n    assert snapshot.agents[0].turn == 9\n\n\ndef test_checkpoint_inspection_counts_immutable_segments(tmp_path: Path) -> None:\n    session = tmp_path / "session"\n    reference = "root/epoch-001-aaaaaaaaaaaaaaaa-bbbbbbbbbbbbbbbb.json"\n    checkpoint = session / ".cambium" / "checkpoints" / reference\n    checkpoint.parent.mkdir(parents=True)\n    summary = SUMMARY_ENTRY_OPEN + \'{"type":"summary_entry"}\' + SUMMARY_ENTRY_CLOSE\n    document = {\n        "provider_messages": [\n            {"role": "system", "content": "system"},\n            {"role": "user", "content": "task"},\n            {"role": "user", "content": summary},\n            {"role": "user", "content": summary},\n        ],\n        "continuation_suffix": [\n            {"role": "assistant", "content": "working"},\n            {"role": "user", "content": "tool result"},\n        ],\n    }\n    checkpoint.write_text(json.dumps(document), encoding="utf-8")\n    events = [\n        _event(\n            1,\n            "context_checkpoint",\n            task_id="root",\n            epoch=1,\n            checkpoint_ref=reference,\n            cache_key={"prefix_bytes": 900, "message_count": 4},\n        )\n    ]\n\n    snapshot = snapshot_from_events(events, session_dir=session)\n\n    assert snapshot.context.checkpoint_ref == reference\n    assert snapshot.context.summary_segments == 2\n    assert snapshot.context.summary_trunk_bytes > snapshot.context.stable_head_bytes\n    assert snapshot.context.raw_tail_bytes > 0\n    assert snapshot.context.estimated_trunk_tokens > 0\n\n\ndef test_dashboard_and_status_render_core_introspection(tmp_path: Path) -> None:\n    snapshot = snapshot_from_events(\n        [\n            _event(1, "spawned", task_id="root"),\n            _event(\n                2,\n                "usage_event",\n                task_id="root",\n                provider="codex",\n                model="gpt",\n                latency_s=2.0,\n                usage={"input_tokens": 10, "output_tokens": 4, "total_tokens": 14},\n            ),\n        ]\n    )\n    dashboard = "\\n".join(\n        render_dashboard(snapshot, session_dir=tmp_path, width=120, height=24)\n    )\n    status = "\\n".join(render_agent_lines(snapshot))\n    assert "codex/gpt" in dashboard\n    assert "out/s=2.0" in dashboard\n    assert "main" in status\n    assert "tokens=14" in status\n')
write('tests/scenarios/test_operator_upgrade.py', '"""OAuth and DSPy operator-path regressions."""\n\nfrom __future__ import annotations\n\nimport json\nimport time\nfrom pathlib import Path\nfrom typing import Any\n\nimport pytest\n\nfrom cambium import cli, oauth, optimize\nfrom cambium.modules.base import Example\nfrom cambium.oauth import OAuthDoc, OAuthStore, RefreshedTokens, TokenManager\nfrom cambium.provider_config import CODEX_CHATGPT_PROFILE\n\n\ndef test_empty_oauth_client_override_uses_pinned_public_client(\n    tmp_path: Path, monkeypatch: pytest.MonkeyPatch\n) -> None:\n    store = OAuthStore(tmp_path / "oauth.json")\n    store.save_provider(\n        OAuthDoc(\n            provider="codex",\n            access_token="expired-access",\n            refresh_token="refresh-token",\n            expires_at=time.time() - 10,\n            account_id="account",\n        )\n    )\n    observed: dict[str, str] = {}\n\n    def refresh(\n        issuer: str,\n        client_id: str,\n        refresh_token: str,\n        timeout_s: float,\n    ) -> RefreshedTokens:\n        del issuer, refresh_token, timeout_s\n        observed["client_id"] = client_id\n        return RefreshedTokens(access_token="fresh-access", expires_in=3600)\n\n    monkeypatch.setattr(oauth, "refresh_access_token", refresh)\n    token, account = TokenManager("codex", store, client_id="").ensure_fresh()\n\n    assert token == "fresh-access"\n    assert account == "account"\n    assert observed["client_id"] == CODEX_CHATGPT_PROFILE["client_id"]\n\n\nclass _CandidateLoader:\n    def __init__(self, path: Path) -> None:\n        self.path = Path(path)\n        self.datasets_dir = self.path if self.path.is_dir() else self.path.parent\n\n    def load(self) -> list[Example]:\n        records = [\n            json.loads(line)\n            for line in self.path.read_text(encoding="utf-8").splitlines()\n            if line.strip()\n        ]\n        return [\n            Example(\n                input=record["input"],\n                expected=record["expected"],\n                canary=bool(record.get("canary", False)),\n            )\n            for record in records\n        ]\n\n\ndef _candidate(identifier: str, status: str) -> dict[str, Any]:\n    return {\n        "id": identifier,\n        "candidate": True,\n        "review_status": status,\n        "redacted": True,\n        "input": {"task": identifier, "context": ""},\n        "expected": {"decompose": False, "reason": "reviewed"},\n    }\n\n\ndef test_transcript_candidates_fail_closed_while_review_is_pending(\n    tmp_path: Path,\n) -> None:\n    path = tmp_path / "transcript_candidates.jsonl"\n    path.write_text(json.dumps(_candidate("pending", "needs_review")) + "\\n")\n    loader = _CandidateLoader(tmp_path)\n\n    with pytest.raises(optimize.OptimizeError, match="still need review"):\n        optimize._load_transcript_candidates(loader, path)\n\n\ndef test_transcript_candidates_load_only_approved_records(tmp_path: Path) -> None:\n    path = tmp_path / "transcript_candidates.jsonl"\n    path.write_text(\n        "\\n".join(\n            [\n                json.dumps(_candidate("approved", "approved")),\n                json.dumps(_candidate("rejected", "rejected")),\n            ]\n        )\n        + "\\n",\n        encoding="utf-8",\n    )\n    loader = _CandidateLoader(tmp_path)\n\n    records = optimize._load_transcript_candidates(loader, path)\n\n    assert len(records) == 1\n    assert records[0].input["task"] == "approved"\n\n\ndef test_cli_exposes_monitor_and_optimizer_commands() -> None:\n    monitor = cli._build_parser().parse_args(["monitor", "--once"])\n    optimizer = cli._build_parser().parse_args(\n        ["optimize", "should_decompose", "--dry-run"]\n    )\n    assert monitor.command == "monitor"\n    assert optimizer.command == "optimize"\n    assert optimizer.module_name == "should_decompose"\n')
write('README.md', '# Cambium\n\nCambium is a Python 3.14 multi-agent coding harness with durable events,\nprovider routing, append-only context trunks, Git worktree isolation, and\nreplayable supervision.\n\nRun it from the checkout:\n\n```sh\nuv sync --extra dev --python 3.14\nuv run cambium --help\n```\n\n## Main commands\n\n```sh\n# One coding task\nuv run cambium run "review and improve the repository" --repo .\n\n# Interactive prompt loop; a live dashboard replaces the screen while a run is active\nuv run cambium tui --repo .\n\n# Attach a dashboard to any running or completed durable session\nuv run cambium monitor /path/to/session\nuv run cambium-monitor /path/to/session\n\n# Inspect durable state without a full-screen terminal\nuv run cambium monitor /path/to/session --once\nuv run cambium monitor /path/to/session --json\n\n# Session recovery and accounting\nuv run cambium session status --session-dir ROOT SESSION\nuv run cambium session usage --session-dir ROOT SESSION\nuv run cambium session resume /path/to/session\n\n# DSPy decision-module optimization\nuv run cambium optimize should_decompose --dry-run\nuv run cambium optimize should_decompose --optimizer bootstrap --budget-usd 2\n```\n\nOther command groups are `auth`, `supervisor`, `doctor`, `bench`,\n`module-test`, `repl`, `architectus`, and `version`.\n\n## Operator dashboard\n\nThe dashboard is an event-sourced read model. It shows:\n\n- main and child-agent lifecycle state;\n- provider/model, generation, turn, epoch, and current tool per agent;\n- input, output, cached, and total tokens per agent;\n- output tokens/second and estimated cost;\n- exact latest prompt tokens when the provider reports them;\n- append-only summary-trunk segments and byte-derived trunk/raw-tail estimates;\n- recent durable events and failures.\n\nThe frontend does not inspect live worker objects. Replaying the same event log\nand checkpoints produces the same dashboard state.\n\n## Context model\n\nProvider-backed agents use:\n\n```text\nstable head + S1 + S2 + ... + Sn + bounded raw tail\n```\n\nEach summary entry covers one disjoint raw range once. Earlier summary bytes are\nnever summarized or rewritten. Compatible children reuse the exact prefix;\nincompatible providers receive the semantic summary history under a fresh\nprovider-specific head.\n\n## Documentation\n\n- [`agents.md`](agents.md) — repository operating contract.\n- [`docs/architecture/architecture.md`](docs/architecture/architecture.md) —\n  runtime and ownership boundaries.\n- [`docs/architecture/context-engine.md`](docs/architecture/context-engine.md) —\n  append-only context epochs and cache reuse.\n- [`docs/architecture/provider-routing.md`](docs/architecture/provider-routing.md) —\n  provider feasibility, routing, and accounting.\n- [`docs/architecture/terminal-interface.md`](docs/architecture/terminal-interface.md) —\n  implemented dashboard contract.\n- [`docs/architecture/optimization.md`](docs/architecture/optimization.md) —\n  DSPy data and evaluation contract.\n- [`docs/security/threat-model.md`](docs/security/threat-model.md) — active\n  no-sandbox threat model.\n- [`docs/research/README.md`](docs/research/README.md) — retained measurements\n  and research evidence.\n\nSource and tests are authoritative when documentation disagrees.\n')
write('docs/README.md', '# Cambium documentation\n\nSource and tests define current behavior.\n\n## Active contracts\n\n- [`architecture/architecture.md`](architecture/architecture.md) — runtime,\n  ownership, publication, and concurrency.\n- [`architecture/context-engine.md`](architecture/context-engine.md) —\n  append-only summary trunks, epochs, forks, resume, and accounting.\n- [`architecture/provider-routing.md`](architecture/provider-routing.md) —\n  provider feasibility, routing, cache affinity, and debt.\n- [`architecture/terminal-interface.md`](architecture/terminal-interface.md) —\n  event-sourced TUI and monitor.\n- [`architecture/optimization.md`](architecture/optimization.md) — DSPy and\n  OpenCode-data gates.\n- [`architecture/user-cli.md`](architecture/user-cli.md) — command reference.\n- [`architecture/module-template/`](architecture/module-template/) — module\n  contract.\n- [`security/threat-model.md`](security/threat-model.md) — no-sandbox trust\n  boundary.\n\n## Retained research\n\nOnly active plans and measured evidence remain under\n[`research/`](research/README.md). Superseded reviews and roadmap snapshots are\navailable through Git history rather than duplicated in the working tree.\n')
write('docs/architecture/terminal-interface.md', '# Terminal observability\n\n**Status:** implemented contract. Source and tests are authoritative.\n\n## Architecture\n\nCambium exposes one event-sourced operator read model:\n\n```text\nworkers and supervisor\n        │\n        ▼\ndurable ordered events + immutable context checkpoints\n        │\n        ▼\nObservabilityState reducer\n        ├── `cambium tui` live frame\n        ├── `cambium monitor` attach/watch\n        ├── `cambium monitor --once`\n        └── `cambium monitor --json`\n```\n\nThe reducer owns no provider, worker, branch, or context state. It folds ordered\nfacts into a projection. This is CQRS/event sourcing: runtime commands mutate\nthe system; the UI reads a replayable projection.\n\n## Dashboard fields\n\nEach agent row exposes:\n\n- role: main or sub-agent;\n- queued, starting, active, merging, succeeded, failed, cancelled, or exited;\n- parent task, generation, turn, and context epoch;\n- provider/model and latest tool;\n- calls and summary calls;\n- input, output, cached, and total tokens;\n- latest output tokens/second;\n- estimated cost.\n\nThe session header exposes aggregate lifecycle counts, usage, cost, output\nthroughput, elapsed time, event cursor, and recent failures.\n\nThe context line exposes:\n\n- exact latest prompt tokens when provider usage supplies them;\n- active prompt bytes and message count;\n- immutable summary-trunk bytes and segment count;\n- raw-tail bytes;\n- byte-derived token estimates marked with `≈`.\n\nByte estimates are never presented as provider-tokenizer truth.\n\n## Runtime instrumentation\n\nEvery provider call emits a validated `usage_event`. In addition to raw provider\nusage, the worker records content-free prompt-shape metadata:\n\n```text\ncall_kind\nactive_context_bytes\nactive_context_messages\nsummary_trunk_bytes\nsummary_segments\nraw_tail_bytes\n```\n\nUnknown or invalid fields fail the usage event at the supervisor boundary.\nPrompt contents never enter these metrics.\n\n## Frontends\n\n`cambium tui` remains the prompt-owning frontend. On a TTY it enters an\nalternate screen only while a run is active and redraws the dashboard from\nevents. Non-TTY output stays line-oriented.\n\n`cambium monitor [SESSION]` attaches to an existing session. With no explicit\npath it uses `CAMBIUM_SESSION_ID` or the newest repository-local session.\n`--once` renders one text frame; `--json` emits one machine-readable snapshot.\n\nClosing a monitor never cancels the runtime. Cancellation remains owned by the\nprocess that started the session.\n\n## Correctness properties\n\n- Replaying an event prefix is deterministic.\n- A missing event cannot be reconstructed from live objects.\n- The reducer is tolerant of unknown event kinds.\n- Terminal lifecycle states are not overwritten by later nonterminal noise.\n- Per-agent totals sum to session totals.\n- Cached tokens are a subset of input and are not added to total twice.\n- Output throughput uses output tokens, not prompt tokens.\n- Checkpoint paths are confined to the session before inspection.\n- The UI never renders arbitrary event payloads; only selected redacted fields\n  enter recent-event summaries.\n')
write('docs/architecture/optimization.md', '# DSPy optimization and OpenCode data\n\n**Status:** executable contract.\n\n## Commands\n\n```sh\nuv run cambium optimize should_decompose --dry-run\nuv run cambium optimize should_decompose --optimizer zero --budget-usd 2\nuv run cambium optimize should_decompose --optimizer bootstrap --budget-usd 2\n```\n\nThe optimizer writes one replace-in-place artifact set:\n\n```text\noptimized/<module>/\n  program.json\n  lm.json\n  report.json\n```\n\nA failed gate does not become a runtime default.\n\n## OpenCode extraction\n\nThe extractor reads one or more OpenCode SQLite databases:\n\n```sh\nuv run python scripts/extract_opencode_transcript_candidates.py \\\n  --database ~/.local/share/opencode/opencode.db \\\n  --output reviewed-candidates.jsonl\n```\n\nExtraction is schema-aware, read-only, bounded, deduplicated, and redacts\ncredentials, personal identifiers, local paths, URLs with credentials, and\nsensitive code blocks. Extracted records start with:\n\n```json\n{"candidate": true, "review_status": "needs_review", "redacted": true}\n```\n\nThey are not training data yet.\n\n## Review gate\n\nDSPy accepts transcript candidates only when each admitted record has:\n\n```json\n{"candidate": true, "review_status": "approved", "redacted": true}\n```\n\n`rejected`/`excluded` records are ignored. Any remaining `needs_review` or\nunknown status fails closed. This prevents an opt-in flag from silently turning\nraw model output into labels.\n\nUse either the module-local reviewed file:\n\n```sh\nuv run cambium optimize should_decompose \\\n  --include-transcript-candidates\n```\n\nor an explicit reviewed file:\n\n```sh\nuv run cambium optimize should_decompose \\\n  --transcript-candidates /path/to/reviewed-candidates.jsonl\n```\n\n## Split discipline\n\nDo not randomly split adjacent turns from the same coding session. Training,\nvalidation, evaluation, and canaries must be separated by source session and,\nwhere possible, repository and time. Otherwise near-duplicate trajectories leak\nacross splits and invalidate the measured gain.\n\nThe frozen evaluation and canary sets never receive transcript candidates.\nCandidate deduplication uses canonical `(task, context)` pairs and excludes\ncollisions with every frozen split.\n\n## Provider and OAuth behavior\n\nThe optimizer uses the same provider configuration and Diffundo transport as the\nruntime. Codex ChatGPT OAuth credentials are refreshed through `TokenManager`\nbefore the LM is constructed; an expired access token is never passed directly\nto DSPy. The public Codex client identifier is pinned in the provider profile,\nwith `CAMBIUM_CODEX_CLIENT_ID` retained only as an override.\n\n## Promotion gate\n\nA compiled program is promotable only when:\n\n- frozen evaluation meets the absolute threshold;\n- it does not regress beyond the baseline tolerance;\n- every canary passes;\n- budget accounting is complete;\n- the artifact and report are written atomically.\n\nTrain gain without held-out/canary gain is reported as an anti-reward gap, not\nas evidence of improvement.\n')
write('docs/architecture/user-cli.md', '# Cambium CLI\n\nSource and scenario tests are authoritative.\n\n## Coding sessions\n\n```sh\ncambium run PROMPT [--repo PATH] [--provider NAME[:MODEL]]\n                   [--model [NAME/]MODEL] [--auto]\n                   [--max-wall-s N] [--max-tokens N] [--max-turns N]\n                   [--session-dir DIR] [--json]\n\ncambium repl [the same routing and budget options]\ncambium tui  [the same routing and budget options] [--quiet]\n```\n\n`run` executes one prompt. `repl` and `tui` accept multiple prompts, each as a\nseparate durable one-shot session leaf. On a TTY, `tui` displays the live\noperator dashboard while the current run is active.\n\n## Monitoring\n\n```sh\ncambium monitor [SESSION] [--repo PATH] [--interval SECONDS] [--once] [--json]\ncambium-monitor [the same arguments]\n```\n\nWithout `SESSION`, discovery checks `CAMBIUM_SESSION_ID` and then the newest\nrepository-local session. `--once` prints one frame. `--json` emits the exact\nreducer snapshot. A monitor is read-only and never cancels a session.\n\n## Session inspection and recovery\n\n```sh\ncambium session list   [--session-dir ROOT]\ncambium session latest [--session-dir ROOT]\ncambium session show   [--session-dir ROOT] SESSION\ncambium session status [--session-dir ROOT] SESSION\ncambium session usage  [--session-dir ROOT] SESSION\ncambium session resume SESSION\n```\n\n`status` and `usage` read the durable event database. `resume` requires the\npersisted `plan.json`.\n\n## DSPy\n\n```sh\ncambium optimize MODULE [--optimizer zero|bootstrap]\n                        [--budget-usd N] [--seed N] [--tier TIER]\n                        [--dry-run]\n                        [--include-transcript-candidates |\n                         --transcript-candidates PATH]\n```\n\nTranscript candidates must pass the explicit approval/redaction gate described\nin `optimization.md`.\n\n## Authentication\n\n```sh\ncambium auth set PROVIDER [--stdin]\ncambium auth remove PROVIDER\ncambium auth list\ncambium auth oauth login PROVIDER [--client-id ID]\ncambium auth oauth status PROVIDER\ncambium auth oauth logout PROVIDER\ncambium auth oauth import-codex-cli\n```\n\nThe Codex public OAuth client identifier is pinned. `--client-id` and\n`CAMBIUM_CODEX_CLIENT_ID` override it; they are not required for the normal\nprofile. Refresh tokens remain in the supervisor-owned OAuth store and are\nnever injected into workers.\n\n## Supervisor and diagnostics\n\n```sh\ncambium supervisor --session-dir DIR (--plan PATH | --task-spec PATH | --demo)\n                   [--warm-pool-size N] [--conversations]\ncambium doctor [--session-dir DIR] [--oauth-live]\ncambium bench {report,gate,re-anchor,quality} [...]\ncambium module-test NAME\ncambium architectus [...]\ncambium version\n```\n\nProvider config comes from the trusted user path\n`~/.config/cambium/providers.json` or explicit `CAMBIUM_PROVIDERS`; target\nrepositories cannot supply it implicitly.\n')
write('docs/research/README.md', '# Retained research\n\nResearch is evidence, not runtime authority. Source, tests, and\n`docs/architecture/` win on disagreement.\n\nRetained files:\n\n- [`cache-first-context-reuse-plan.md`](cache-first-context-reuse-plan.md) —\n  original cache-first hypothesis and acceptance evidence.\n- [`rolling-context-and-agent-reuse.md`](rolling-context-and-agent-reuse.md) —\n  rolling context and child-agent reuse analysis.\n- [`worker-coldstart.md`](worker-coldstart.md) — measured process/import costs.\n- [`sqlite-wal-durability.md`](sqlite-wal-durability.md) — measured event-store\n  durability behavior.\n- [`bench-harness-design.md`](bench-harness-design.md) — benchmark/evaluation\n  design.\n- [`test-strategy.md`](test-strategy.md) — testing principles and tiers.\n- [`coding-constitution.md`](coding-constitution.md) — active engineering\n  constraints.\n\nSuperseded critique dispositions, status snapshots, pre-implementation reviews,\nprovider comparisons, and abandoned design branches were removed. Git history\npreserves them when forensic context is needed.\n')
write('docs/research/coding-constitution.md', '# Engineering constitution\n\nCambium is a correctness-first concurrent systems harness.\n\n## Rules\n\n1. **Single ownership.** Each mutable state domain has one owner: worker,\n   supervisor, event-store writer, merge publisher, or session reducer.\n2. **Messages over shared mutation.** Processes and actors communicate through\n   bounded, validated messages. Cross-thread shared mutable state is avoided.\n3. **Functional core, imperative shell.** Parsing, validation, routing,\n   reducers, and metrics are pure where practical; process, Git, network, and\n   persistence effects stay at explicit boundaries.\n4. **Event sourcing for observation.** User interfaces and recovery projections\n   derive from durable ordered facts, never from ad-hoc inspection of live\n   objects.\n5. **Fail closed at trust boundaries.** Unknown wire fields, malformed\n   credentials, corrupt checkpoints, stale generations, and unsafe paths are\n   rejected before side effects.\n6. **Append-only context.** Summary segments cover disjoint raw ranges once.\n   Existing summaries and published epochs are immutable.\n7. **Mechanical sympathy follows measurement.** Optimize the measured\n   bottleneck. Provider RTT and model latency dominate microsecond Python\n   bookkeeping; worker cold-start evidence justifies pooling.\n8. **Data-oriented hot paths.** Keep event and routing records flat,\n   canonical, bounded, and cheap to validate.\n9. **Backpressure is explicit.** Critical events are never silently dropped.\n   Noncritical coalescing/dropping is typed and observable.\n10. **Publication is transactional.** Verify and publish under fencing and\n    expected-old references. A successful model response is not publication.\n11. **Tests defend invariants, not implementation trivia.** Retain boundary,\n    replay, cancellation, accounting, fencing, auth, and corruption tests.\n    Consolidate duplicated formatting and fixture tests.\n12. **Unknown is not zero.** Missing price, token, cache, latency, and context\n    measurements remain unknown or approximate and are labeled accordingly.\n\n## Formal mappings\n\n- Actor model / CSP: supervisor, workers, store writer, and monitor reducer.\n- State machines: worker lifecycle, task lifecycle, context epochs, OAuth\n  refresh, and merge publication.\n- Event sourcing and CQRS: durable events plus read-only projections.\n- Linearizability: fenced generation changes and expected-old Git ref updates.\n- Write-ahead logging: SQLite WAL event persistence.\n- Content addressing: immutable context checkpoints.\n- Map-reduce/fold: usage and observability aggregation.\n')

